"""Conditional density of y (supported on about [0.95, 1.0]).

t: estimate of y, a polynomial in u = x0 (Horner form) whose coefficients are linear in
the covariate tuples Xa, Xb, Xd and the products Xc; s: noise scale, log-quadratic in u.
The density is a skew-normal approximation of normal(t, s) truncated to the support
[cen - hw, cen + hw]: d is the distance, in units of s, from t to the nearest edge, side is
+1 near the lower edge and -1 near the upper one, and the skew-normal offset, scale and shape
are smooth functions of d (the density tends to normal(t, s) far from the edges)."""
from adr.dist import SkewNormal, exp, dot, abs, maximum


def model(x):
    u = x[0] - 5.0
    Xa = x[1:7]
    Xb = x[12:16]
    Xc = (x[9] * x[9], x[7] * x[7], x[12] * x[12], x[4] * x[4])
    Xd = x[7:11]
    t = -11.681280339763576 + dot((0.002981672571654921, 2.0587877174931637e-06, 2.3209374457009312e-05, 0.000674759556373112, 4.215270649723208e-05, 3.898813472390935e-05), Xa) + dot((-0.13384093500200434, 2.2374856948469013, 0.0007369848640546907, 0.07562341565067542), Xb) + dot((-0.0008639475546907216, 0.027130442534425935, 0.005635524613178301, 0.06536047080311293), Xd) + dot((-6.7586024027663e-06, 5.44777173967857e-07, 0.007565298099479484, -4.828189963208876e-08), Xc) + u * (-4.017638366735596 + dot((-0.0009564299366850541, -7.279565995707232e-07, -5.979640580257094e-06, 0.0004760134550668084, -1.9941881678309372e-05, -2.3976394469697828e-05), Xa) + dot((0.003242327255389166, -0.2111515079302299, 6.009327036305407e-05, -0.01301300385607748), Xb) + dot((-0.0004706015340153063, 0.005201568306053231, 0.0029735371364713616, -0.006016140132282254), Xd) + dot((-2.1383770391571585e-06, 3.427342869053531e-07, -0.001709233880387029, -2.6634412123534608e-08), Xc) + u * (-0.18889894668129617 + dot((0.012722443407651036, -0.02234726442989576, -6.540154315829289e-05, -0.0009432508441840072), Xb) + dot((1.8987023187376037e-07, -5.570581690472527e-08, -0.0004225605087490324, 1.3358357975338755e-09), Xc) + u * (-0.025604962564580353 + dot((1.9833902533426065e-08, -6.708615737992542e-09, 0.0001326315878454178, -2.685216018907468e-11), Xc) + u * (0.0009721531854632177 + dot((-4.884865024594818e-09, 2.136838658436162e-09, -1.5171061209186343e-05, -2.054739940179181e-12), Xc) + u * (0.00022098695179582838)))))
    s = exp(-5.7074409284194845 + u * (-0.07867665144134273 + u * -0.021057694924109253))
    a = 0.9750081539278926 - t
    d = maximum((0.025145854091757316 - abs(a)) / s, -3.0)
    side = a / abs(a)
    w = d * exp(-0.17163516886016877 * d * d)
    return SkewNormal(t - side * s * w, s * exp(0.3205078775738791 * w), side * exp(2.1145966768250473 - 0.8767309002744563 * d))
